-- Initial Pulsari Desk schema generated for PostgreSQL.
CREATE TYPE "UserRole" AS ENUM ('ADMIN','TECHNICIAN','CLIENT_MANAGER','CLIENT_USER');
CREATE TYPE "UserStatus" AS ENUM ('ACTIVE','INACTIVE','INVITED');
CREATE TYPE "CompanyStatus" AS ENUM ('ACTIVE','INACTIVE','SUSPENDED');
CREATE TYPE "SystemType" AS ENUM ('INSTITUTIONAL_SITE','LANDING_PAGE','DASHBOARD','WEB_SYSTEM','MOBILE_SYSTEM','API','AUTOMATION','INTEGRATION','ECOMMERCE','OTHER');
CREATE TYPE "SystemStatus" AS ENUM ('ACTIVE','INACTIVE','MAINTENANCE','ARCHIVED');
CREATE TYPE "TicketCategory" AS ENUM ('SYSTEM_ERROR','USAGE_QUESTION','CHANGE_REQUEST','IMPROVEMENT','ACCESS_PROBLEM','SLOWNESS','REPORT_DASHBOARD','INTEGRATION_API','PUBLISHING','OTHER');
CREATE TYPE "TicketPriority" AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL');
CREATE TYPE "TicketImpact" AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL');
CREATE TYPE "TicketStatus" AS ENUM ('NEW','TRIAGE','IN_PROGRESS','WAITING_CLIENT','WAITING_THIRD_PARTY','DEVELOPMENT','TESTING','RESOLVED','CLOSED','REOPENED','CANCELED');
CREATE TYPE "CommentType" AS ENUM ('PUBLIC','INTERNAL');
CREATE TYPE "PlanStatus" AS ENUM ('ACTIVE','INACTIVE');
CREATE TYPE "ContractStatus" AS ENUM ('ACTIVE','PAUSED','CANCELED','EXPIRED');
CREATE TYPE "BalanceStatus" AS ENUM ('OPEN','CLOSED','ADJUSTED');
CREATE TYPE "ActivityType" AS ENUM ('TRIAGE','CUSTOMER_SUPPORT','TECHNICAL_ANALYSIS','BUG_FIX','VISUAL_ADJUSTMENT','DEVELOPMENT','TESTING','MEETING','DOCUMENTATION','DEPLOY','TRAINING','LOG_INVESTIGATION','INTEGRATION','OTHER');
CREATE TYPE "BillingType" AS ENUM ('DEDUCTIBLE','NON_DEDUCTIBLE','EXTRA','COURTESY');
CREATE TYPE "ArticleVisibility" AS ENUM ('INTERNAL','CLIENTS','BOTH');
CREATE TYPE "ArticleStatus" AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');

CREATE TABLE "Company" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "tradeName" TEXT, "cnpj" TEXT, "email" TEXT NOT NULL, "phone" TEXT, "responsibleName" TEXT NOT NULL, "status" "CompanyStatus" NOT NULL DEFAULT 'ACTIVE', "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Company_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Company_email_key" ON "Company"("email");
CREATE TABLE "User" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'CLIENT_USER', "companyId" TEXT, "avatarUrl" TEXT, "status" "UserStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "ClientSystem" ("id" TEXT NOT NULL, "companyId" TEXT NOT NULL, "name" TEXT NOT NULL, "type" "SystemType" NOT NULL, "productionUrl" TEXT, "stagingUrl" TEXT, "description" TEXT, "status" "SystemStatus" NOT NULL DEFAULT 'ACTIVE', "responsibleUserId" TEXT, "deliveryDate" TIMESTAMP(3), "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ClientSystem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Ticket" ("id" TEXT NOT NULL, "code" TEXT NOT NULL, "companyId" TEXT NOT NULL, "requesterId" TEXT NOT NULL, "systemId" TEXT, "assigneeId" TEXT, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "attemptedAction" TEXT, "actualResult" TEXT, "expectedResult" TEXT, "occursSince" TEXT, "affectedUsers" TEXT, "category" "TicketCategory" NOT NULL, "priority" "TicketPriority" NOT NULL DEFAULT 'MEDIUM', "status" "TicketStatus" NOT NULL DEFAULT 'NEW', "impact" "TicketImpact" NOT NULL DEFAULT 'MEDIUM', "origin" TEXT NOT NULL DEFAULT 'portal', "tags" TEXT[] DEFAULT ARRAY[]::TEXT[], "isImprovement" BOOLEAN NOT NULL DEFAULT false, "isOutOfScope" BOOLEAN NOT NULL DEFAULT false, "isBillable" BOOLEAN NOT NULL DEFAULT true, "totalMinutes" INTEGER NOT NULL DEFAULT 0, "firstResponseAt" TIMESTAMP(3), "resolvedAt" TIMESTAMP(3), "closedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Ticket_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Ticket_code_key" ON "Ticket"("code");
CREATE TABLE "TicketComment" ("id" TEXT NOT NULL, "ticketId" TEXT NOT NULL, "userId" TEXT NOT NULL, "content" TEXT NOT NULL, "type" "CommentType" NOT NULL DEFAULT 'PUBLIC', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "TicketComment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TicketAttachment" ("id" TEXT NOT NULL, "ticketId" TEXT NOT NULL, "commentId" TEXT, "fileName" TEXT NOT NULL, "fileUrl" TEXT NOT NULL, "fileType" TEXT NOT NULL, "fileSize" INTEGER NOT NULL, "uploadedById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TicketAttachment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TicketHistory" ("id" TEXT NOT NULL, "ticketId" TEXT NOT NULL, "userId" TEXT, "action" TEXT NOT NULL, "oldValue" TEXT, "newValue" TEXT, "description" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TicketHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupportPlan" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "monthlyHours" INTEGER NOT NULL, "monthlyPrice" DECIMAL(10,2) NOT NULL, "extraHourPrice" DECIMAL(10,2) NOT NULL DEFAULT 0, "allowRollover" BOOLEAN NOT NULL DEFAULT false, "rolloverLimit" INTEGER, "allowExtraHours" BOOLEAN NOT NULL DEFAULT true, "requireExtraApproval" BOOLEAN NOT NULL DEFAULT true, "status" "PlanStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SupportPlan_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SupportPlan_name_key" ON "SupportPlan"("name");
CREATE TABLE "ClientSupportContract" ("id" TEXT NOT NULL, "companyId" TEXT NOT NULL, "supportPlanId" TEXT NOT NULL, "startDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "renewalDay" INTEGER NOT NULL DEFAULT 1, "status" "ContractStatus" NOT NULL DEFAULT 'ACTIVE', "customMonthlyHours" INTEGER, "customPrice" DECIMAL(10,2), "notes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ClientSupportContract_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupportHourBalance" ("id" TEXT NOT NULL, "contractId" TEXT NOT NULL, "companyId" TEXT NOT NULL, "month" INTEGER NOT NULL, "year" INTEGER NOT NULL, "openingMinutes" INTEGER NOT NULL, "usedMinutes" INTEGER NOT NULL DEFAULT 0, "remainingMinutes" INTEGER NOT NULL, "extraMinutes" INTEGER NOT NULL DEFAULT 0, "courtesyMinutes" INTEGER NOT NULL DEFAULT 0, "nonBillableMinutes" INTEGER NOT NULL DEFAULT 0, "status" "BalanceStatus" NOT NULL DEFAULT 'OPEN', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SupportHourBalance_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SupportHourBalance_companyId_month_year_key" ON "SupportHourBalance"("companyId","month","year");
CREATE TABLE "SupportHourEntry" ("id" TEXT NOT NULL, "ticketId" TEXT NOT NULL, "companyId" TEXT NOT NULL, "contractId" TEXT NOT NULL, "userId" TEXT NOT NULL, "date" TIMESTAMP(3) NOT NULL, "durationMinutes" INTEGER NOT NULL, "activityType" "ActivityType" NOT NULL, "description" TEXT NOT NULL, "billingType" "BillingType" NOT NULL, "balanceAfterMinutes" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SupportHourEntry_pkey" PRIMARY KEY ("id"));
CREATE TABLE "KnowledgeArticle" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "category" TEXT NOT NULL, "content" TEXT NOT NULL, "systemId" TEXT, "visibility" "ArticleVisibility" NOT NULL DEFAULT 'BOTH', "status" "ArticleStatus" NOT NULL DEFAULT 'DRAFT', "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "KnowledgeArticle_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Notification" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "title" TEXT NOT NULL, "message" TEXT NOT NULL, "type" TEXT NOT NULL, "read" BOOLEAN NOT NULL DEFAULT false, "relatedTicketId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Notification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL, "userId" TEXT, "action" TEXT NOT NULL, "entity" TEXT NOT NULL, "entityId" TEXT NOT NULL, "description" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));

